"""Schema-faithful semantic SVG. Positions are layout, not a background image."""
from html import escape
NODES=[('lots',40,80,'Production genealogy',['PK lot_id','product · period · material_batch']),('wafers',340,80,'Production genealogy',['PK wafer_id','FK lot_id']),('packages',640,80,'Production genealogy',['PK package_id','FK wafer_id, lot_id','UNIQUE wafer_id + die_site']),('test_results',980,80,'Quality evidence',['PK test_id','FK package_id, run_id, subdivision_id','UNIQUE package_id + attempt']),('process_steps',40,330,'Reference data',['PK process_id','stage · unit_level · parameter']),('equipment',40,550,'Reference data',['PK subdivision_id','FK process_id','equipment_id groups subdivisions']),('process_runs',490,330,'Process execution',['PK run_id','FK wafer_id, lot_id, process_id','FK subdivision_id; package_id*']),('measurements',980,330,'Quality evidence',['PK measurement_id','FK run_id (UNIQUE)','0..1 sampled observation / run']),('defects',980,550,'Quality evidence',['PK defect_id','FK run_id, defect_code']),('equipment_events',40,770,'Process execution',['PK event_id','FK subdivision_id']),('defect_catalog',980,770,'Reference data',['PK defect_code','FK process_id'])]
# Explicit orthogonal routes; ancillary ancestry FKs are in boxes to avoid crossings.
EDGES=[('M300 138 H340','1:N',315,128),('M600 138 H640','1:N',615,128),('M900 138 H980','1:0..2',927,128),('M470 196 V266 H555 V330','1:N',480,255),('M770 196 V284 H680 V330','1:N*',780,265),('M300 388 H490','1:N',385,378),('M170 446 V550','1:N',182,505),('M300 608 H410 V414 H490','1:N',422,510),('M750 388 H980','1:0..1',850,378),('M750 420 H845 V608 H980','1:N',860,596),('M750 350 H930 V175 H980','1:0..2',942,255),('M1110 770 V666','1:N',1123,725),('M170 666 V770','1:N',182,725)]
COLORS={'Production genealogy':('#eaf2ff','#2475db'),'Process execution':('#e8f6f3','#008e83'),'Quality evidence':('#f0f3fa','#6c7f9a'),'Reference data':('#fff5e8','#c48532')}

def model_html():
    svg=['<svg class="model-svg" id="relational-model" viewBox="0 0 1290 960" role="img" aria-labelledby="model-title model-desc" xmlns="http://www.w3.org/2000/svg"><title id="model-title">Manufacturing relational data model</title><desc id="model-desc">Eleven tables grouped into production genealogy, process execution, quality evidence and reference data. Conditional package foreign key and extra ancestry links are documented.</desc><rect width="1290" height="960" fill="#f8fbff"/>']
    for title,x in [('PRODUCTION GENEALOGY',40),('QUALITY EVIDENCE',980)]:svg.append(f'<text x="{x}" y="45" font-family="Arial" font-size="13" font-weight="700" fill="#476784">{title}</text>')
    for path,label,x,y in EDGES:
        svg.append(f'<path d="{path}" fill="none" stroke="#8da7bf" stroke-width="1.5"/><rect x="{x-3}" y="{y-14}" width="54" height="20" rx="4" fill="#f8fbff"/><text x="{x}" y="{y}" font-family="Arial" font-size="12" fill="#52718e">{label}</text>')
    for name,x,y,group,fields in NODES:
        fill,accent=COLORS[group];svg.append(f'<g data-entity="{name}"><rect x="{x}" y="{y}" width="260" height="116" rx="9" fill="white" stroke="#cbdbe9"/><path d="M{x+9} {y} H{x+251} Q{x+260} {y} {x+260} {y+9} V{y+35} H{x} V{y+9} Q{x} {y} {x+9} {y}" fill="{fill}"/><rect x="{x}" y="{y+8}" width="3" height="20" fill="{accent}"/><text x="{x+15}" y="{y+23}" font-family="Arial" font-size="15" font-weight="700" fill="#183956">{name}</text>')
        for i,field in enumerate(fields):svg.append(f'<text x="{x+15}" y="{y+56+i*20}" font-family="Arial" font-size="11.5" fill="#4f6b84">{escape(field)}</text>')
        svg.append('</g>')
    svg.append('<text x="360" y="795" font-family="Arial" font-size="13" font-weight="700" fill="#294a68">CONDITIONAL UNIT CONTEXT</text><text x="360" y="822" font-family="Arial" font-size="12" fill="#58748e">* package_id is required for package runs; blank for wafer runs.</text><text x="360" y="846" font-family="Arial" font-size="12" fill="#58748e">Redundant lot/wafer ancestry is validated, not independently counted.</text><text x="360" y="870" font-family="Arial" font-size="12" fill="#58748e">Retests reference the original final-test run (at most 2 attempts).</text><text x="40" y="935" font-family="Arial" font-size="11.5" fill="#58748e">Additional validated links shown in entity fields: lot ancestry, test subdivision, defect catalog to process steps.</text></svg>')
    return '<div class="model-sheet"><div class="model-toolbar"><strong>Manufacturing relational model</strong><button data-action="model-fit" class="secondary">Fit to view</button><button data-action="model-zoom" class="secondary">Zoom in</button></div><div class="model-viewport">'+''.join(svg)+'</div><p class="model-caption">Colored headers distinguish genealogy, execution, evidence and reference tables. Connectors show principal relationships; extra validated foreign keys are listed in the entity fields.</p></div>'
